?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tiết cố định và tiết đôi – CDS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>body{background:#edf3f8;font-family:Segoe UI,system-ui,sans-serif}.wrap{max-width:1300px}.hero{background:linear-gradient(110deg,#123f64,#2781ba);color:#fff}.card{border:1px solid #d5e0e8;border-radius:14px}.rule-list{max-height:390px;overflow:auto}.rule-row{display:flex;justify-content:space-between;gap:12px;padding:9px;border-top:1px solid #e1e8ee}.form-label{font-weight:700}</style></head><body><header class="hero"><div class="container-fluid wrap py-3 d-flex justify-content-between align-items-center"><div><h3 class="mb-0"><i class="bi bi-link-45deg"></i> Tiết cố định và hai tiết liền nhau</h3><small>Ràng buộc bắt buộc khi tạo lại phương án</small></div><a class="btn btn-outline-light" href="/tkb_constraints.php">Quay lại ràng buộc</a></div></header><main class="container-fluid wrap py-3"><?php show_flash();?><div class="row g-3"><section class="col-lg-6"><div class="card p-3 h-100"><h4>Tiết xếp cố định</h4><p class="text-muted small">Chọn đúng lần xuất hiện của môn trong tuần rồi đặt vào một vị trí duy nhất.</p><form method="post" action="/tkb_xep.php" class="row g-2"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="fixed_lesson_save"><div class="col-12"><label class="form-label">Tiết theo PCCM</label><select class="form-select" name="activity_id" required><option value="">Chọn tiết…</option><?php foreach($activities as$a):if(!empty($a['group_id']))continue;?><option value="<?=e($a['id'])?>"><?=e($a['classes'][0].' · '.$a['subject'].' · '.$a['teacher'].' · lần '.substr(strrchr($a['id'],'_')?:'_1',1))?></option><?php endforeach;?></select></div><div class="col-4"><label class="form-label">Thứ</label><select class="form-select" name="day"><?php foreach($data['settings']['days']as$d):?><option value="<?=$d?>">Thứ <?=$d?></option><?php endforeach;?></select></div><div class="col-4"><label class="form-label">Buổi</label><select class="form-select" name="session"><option>Sáng</option><option>Chiều</option></select></div><div class="col-4"><label class="form-label">Tiết</label><input class="form-control" type="number" name="period" min="1" max="8" value="1"></div><div class="col-12"><button class="btn btn-primary"><i class="bi bi-pin-angle"></i> Cố định tiết</button></div></form><div class="rule-list mt-3"><?php foreach($data['fixed_lessons']as$r):?><div class="rule-row"><span><strong><?=e(implode('+',(array)$r['classes']).' · '.$r['subject'])?></strong><small class="d-block text-muted"><?=e($r['teacher'])?> · Thứ <?=e($r['day'])?> · <?=e($r['session'])?> tiết <?=e($r['period'])?></small></span><form method="post" action="/tkb_xep.php"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="fixed_lesson_delete"><input type="hidden" name="activity_id" value="<?=e($r['activity_id'])?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div><?php endforeach;if(!$data['fixed_lessons']):?><div class="text-muted small">Chưa có tiết cố định.</div><?php endif;?></div></div></section><section class="col-lg-6"><div class="card p-3 h-100"><h4>Hai tiết dạy liền nhau</h4><p class="text-muted small">Mỗi cặp luôn cùng ngày, cùng buổi và ở hai tiết liên tiếp; không bị tách qua giờ nghỉ giữa hai buổi.</p><form method="post" action="/tkb_xep.php" class="row g-2"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="double_lesson_save"><div class="col-9"><label class="form-label">Môn – lớp – giáo viên</label><select class="form-select" name="assignment_id" required><option value="">Chọn phân công…</option><?php foreach($assignments as$a):if((float)$a['periods']<2)continue;?><option value="<?=e($a['id'])?>"><?=e($a['class'].' · '.$a['subject'].' · '.$a['teacher'].' ('.$a['periods'].' tiết)')?></option><?php endforeach;?></select></div><div class="col-3"><label class="form-label">Số cặp/tuần</label><input class="form-control" type="number" name="pairs" min="1" max="5" value="1"></div><div class="col-12"><button class="btn btn-success"><i class="bi bi-link"></i> Lưu tiết đôi</button></div></form><div class="rule-list mt-3"><?php foreach($data['double_lessons']as$r):?><div class="rule-row"><span><strong><?=e($r['class'].' · '.$r['subject'])?></strong><small class="d-block text-muted"><?=e($r['teacher'])?> · <?=e($r['pairs'])?> cặp/tuần</small></span><form method="post" action="/tkb_xep.php"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="double_lesson_delete"><input type="hidden" name="assignment_id" value="<?=e($r['assignment_id'])?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div><?php endforeach;if(!$data['double_lessons']):?><div class="text-muted small">Chưa có môn yêu cầu hai tiết liền nhau.</div><?php endif;?></div></div></section></div><div class="alert alert-info mt-3"><strong>Lưu ý:</strong> Sau khi thay đổi, vào “Xem & chỉnh” và chọn “Xếp lại phương án”. TKB đang công bố không bị thay đổi.</div></main></body></html>
